(function() {
  const tabs = document.querySelectorAll('[role="tabpanel"]');
  const results = [];
  for(let i = 0; i < tabs.length; i++) {
    const t = tabs[i];
    const heading = t.querySelector('h2')?.textContent?.trim() || t.querySelector('h3')?.textContent?.trim() || '';
    if(heading.includes('fwat2-n2 MTP Item A') || heading.includes('Edit')) {
      results.push('TAB ' + i + ': ' + heading);
      // Find status combobox/select
      const selects = t.querySelectorAll('select');
      for(const s of selects) {
        const label = s.labels?.[0]?.textContent?.trim() || s.closest('label')?.textContent?.trim() || '';
        results.push('  select: label="' + label + '" value="' + s.value + '" options=' + Array.from(s.options).map(o => o.value).join(','));
      }
    }
  }
  return results.join('\n') || 'no matching tab found';
})()

